#!/bin/sh
# Create .env with random lab-only secrets. Never overwrites an existing file.
set -eu
cd "$(dirname "$0")/.."
if [ -f .env ]; then
  echo ".env already exists, leaving it alone"
  exit 0
fi
umask 077
cat > .env <<EOF
# Generated by scripts/make-env.sh. Lab-only values, never reuse them anywhere.
POSTGRES_ROOT_PASSWORD=$(openssl rand -hex 16)
VAULT_DEV_ROOT_TOKEN=$(openssl rand -hex 16)
AGENT_KEY=agent-$(openssl rand -hex 16)
UPSTREAM_KEY=upstream-$(openssl rand -hex 16)
SESSION_KEY=$(openssl rand -hex 32)
LLM_MODEL=qwen2.5:3b
EOF
mkdir -p .lab
echo "wrote .env"
